use std::sync::{Arc, Mutex}; use std::thread; use std::time::Duration; use std::io::{BufReader, Lines}; // Start monitoring threads with enhanced logging and crash detection let app_handle_stdout = app_handle.clone(); let status_arc = Arc::clone(&state.status); thread::spawn(move || { let reader = BufReader::new(stdout); let mut initialization_confirmed = false; for line in reader.lines() { match line { Ok(line_content) => { emit_log_entry(&app_handle_stdout, "stdout", line_content.clone()); // Check for successful initialization if line_content.contains("Successfully connected to NATS") { initialization_confirmed = true; let mut status_lock = status_arc.lock().unwrap(); *status_lock = "online".to_string(); emit_log_entry(&app_handle_stdout, "status", "[SUCCESS] Daemon online and ready!".to_string()); } // Check for critical errors if line_content.contains("invalid consumer name") || line_content.contains("Failed to create JetStream pull subscription") { emit_log_entry(&app_handle_stdout, "error", "[FAILED] CRITICAL: Daemon failed due to NATS consumer name issue".to_string()); emit_log_entry(&app_handle_stdout, "error", "REPAIR This is a known bug in the daemon binary - hostname contains invalid characters".to_string()); emit_log_entry(&app_handle_stdout, "error", "TIP UI will continue in fallback mode with mock data".to_string()); let mut status_lock = status_arc.lock().unwrap(); *status_lock = "fallback".to_string(); break; } if line_content.contains("fatal") { emit_log_entry(&app_handle_stdout, "error", "[FAILED] Daemon crashed - entering fallback mode".to_string()); let mut status_lock = status_arc.lock().unwrap(); *status_lock = "fallback".to_string(); break; } } Err(e) => { emit_log_entry(&app_handle_stdout, "error", format!("Error reading stdout: {}", e)); break; } } } // If we exit the loop without confirming initialization, set fallback mode if !initialization_confirmed { let mut status_lock = status_arc.lock().unwrap(); if *status_lock == "starting" { *status_lock = "fallback".to_string(); emit_log_entry(&app_handle_stdout, "status", " Daemon failed to initialize, switching to fallback mode".to_string()); } } }); let app_handle_stderr = app_handle.clone(); thread::spawn(move || { let reader = BufReader::new(stderr); for line in reader.lines() { match line { Ok(line_content) => { emit_log_entry(&app_handle_stderr, "stderr", line_content); } Err(e) => { emit_log_entry(&app_handle_stderr, "error", format!("Error reading stderr: {}", e)); break; } } } }); // Start periodic health check with fallback support let app_handle_health = app_handle.clone(); let status_arc_health = Arc::clone(&state.status); thread::spawn(move || { let mut health_check_count = 0; loop { thread::sleep(Duration::from_secs(30)); health_check_count += 1; let current_status = { let status_lock = status_arc_health.lock().unwrap(); status_lock.clone() }; match current_status.as_str() { "online" => { emit_log_entry(&app_handle_health, "status", "[SUCCESS] Health check: Daemon is running".to_string()); } "fallback" => { emit_log_entry(&app_handle_health, "status", " Health check: Running in fallback mode".to_string()); } _ => { emit_log_entry(&app_handle_health, "status", format!("[WARNING] Health check: Status = {}", current_status)); } } // Stop health checks after 10 minutes for fallback mode if current_status == "fallback" && health_check_count > 20 { emit_log_entry(&app_handle_health, "status", "Health monitoring stopped for fallback mode".to_string()); break; } } }); 